INSERT INTO `uniformAdmin_faqdescription` (`id`, `description`, `isActive`, `isDeleted`, `created_at`, `updated_at`, `faq_id`) VALUES
(25,	'You can customize your uniforms by selecting different fabrics, colors, and specific parts like collars, sleeves, pockets, and cuffs using our interactive customization tool.',	1,	0,	'2026-07-07 10:51:00.663175',	'2026-07-07 10:51:00.663196',	13),
(26,	'Once configured, you can save your custom design as a quotation request or add it directly to your cart.',	1,	0,	'2026-07-07 10:51:00.665075',	'2026-07-07 10:51:00.665098',	13),
(27,	'We offer premium fabric materials including Cotton, Polyester, Silk, and Linen.',	1,	0,	'2026-07-07 10:51:00.671647',	'2026-07-07 10:51:00.671674',	14),
(28,	'Each material type is selected for durability, breathability, and professional appearance.',	1,	0,	'2026-07-07 10:51:00.673903',	'2026-07-07 10:51:00.673934',	14),
(29,	'The standard rental duration depends on your order selection at checkout.',	1,	0,	'2026-07-07 10:51:00.678324',	'2026-07-07 10:51:00.678345',	15),
(30,	'We also offer a 3-day grace period after the return date before any late fees are applied.',	1,	0,	'2026-07-07 10:51:00.680203',	'2026-07-07 10:51:00.680227',	15),
(31,	'Custom uniforms are sized based on standard corporate fit charts.',	1,	0,	'2026-07-07 10:51:00.684609',	'2026-07-07 10:51:00.684638',	16),
(32,	'You can enter specific measurements for each uniform item during the order configuration.',	1,	0,	'2026-07-07 10:51:00.687220',	'2026-07-07 10:51:00.687258',	16),
(33,	'Yes, we provide table linens, runner cloths, and thematic settings under our Table coordination section.',	1,	0,	'2026-07-07 10:51:00.692031',	'2026-07-07 10:51:00.692059',	17),
(34,	'These items can be selected to match your specific event requirements.',	1,	0,	'2026-07-07 10:51:00.694250',	'2026-07-07 10:51:00.694284',	17),
(35,	'Yes, we offer multiple design themes. You can filter and select fabrics, colors, and patterns matching specific Table Themes in the coordination panel.',	1,	0,	'2026-07-07 10:51:00.699263',	'2026-07-07 10:51:00.699295',	18),
(36,	'A damage fee will be assessed depending on the type and extent of damage (e.g. stains, tears).',	1,	0,	'2026-07-07 10:51:00.703094',	'2026-07-07 10:51:00.703123',	19),
(37,	'Details regarding damage fee rates are outlined in our rental terms and conditions.',	1,	0,	'2026-07-07 10:51:00.705089',	'2026-07-07 10:51:00.705118',	19),
(38,	'Absolutely. Event coordinators can submit bulk quotation requests for custom table setups.',	1,	0,	'2026-07-07 10:51:00.709225',	'2026-07-07 10:51:00.709247',	20),
(39,	'Once approved, you will receive a digital contract which can be signed online.',	1,	0,	'2026-07-07 10:51:00.711090',	'2026-07-07 10:51:00.711113',	20),
