INSERT INTO `uniformAdmin_privacypolicy` (`id`, `privacyPolicyType`, `type`, `title`, `slug`, `content`, `language`, `version`, `isActive`, `isDeleted`, `created_at`, `updated_at`) VALUES
(1,	'privacy_and_policy',	'uniform',	'Privacypolicy',	'privacypolicy',	'<p>\r\nAt our company, we are committed to protecting your privacy and ensuring that your\r\npersonal information is handled in a secure and responsible manner. This Privacy\r\nPolicy explains how we collect, use, store, and protect the information you provide\r\nwhile using our website, mobile application, or related services.\r\n</p>\r\n\r\n<h3>5.1 Information We Collect</h3>\r\n\r\n<p>\r\nWe may collect personal information such as your name, email address, phone number,\r\nshipping address, billing address, payment details, and account credentials when you\r\nregister, place an order, or contact our support team. We may also collect technical\r\ninformation including your IP address, browser type, operating system, device\r\ninformation, and website usage statistics.\r\n</p>\r\n\r\n<h3>5.2 How We Use Your Information</h3>\r\n\r\n<p>\r\nYour information is used to provide and improve our services, process transactions,\r\nmanage your account, deliver products, respond to customer inquiries, personalize\r\nyour experience, send important notifications, and comply with applicable legal\r\nrequirements.\r\n</p>\r\n\r\n<h3>5.3 Cookies and Tracking Technologies</h3>\r\n\r\n<p>\r\nWe use cookies and similar technologies to remember your preferences, improve website\r\nperformance, analyze visitor behavior, and provide a better browsing experience.\r\nYou may disable cookies through your browser settings, although some features of the\r\nwebsite may become unavailable.\r\n</p>\r\n\r\n<h3>5.4 Sharing of Information</h3>\r\n\r\n<p>\r\nWe do not sell or rent your personal information. We may share your information with\r\ntrusted third-party service providers such as payment processors, shipping partners,\r\ncloud hosting providers, and analytics services only when necessary to operate our\r\nbusiness or comply with legal obligations.\r\n</p>\r\n\r\n<h3>5.5 Data Security</h3>\r\n\r\n<p>\r\nWe implement industry-standard technical, administrative, and physical safeguards to\r\nprotect your personal information against unauthorized access, disclosure, alteration,\r\nor destruction. While we strive to protect your data, no electronic transmission or\r\nstorage system can be guaranteed to be 100% secure.\r\n</p>\r\n\r\n<h3>5.6 Data Retention</h3>\r\n\r\n<p>\r\nWe retain your personal information only for as long as necessary to fulfill the\r\npurposes outlined in this Privacy Policy, resolve disputes, comply with legal\r\nrequirements, and enforce our agreements.\r\n</p>\r\n\r\n<h3>5.7 Your Rights</h3>\r\n\r\n<p>\r\nDepending on your jurisdiction, you may have the right to access, update, correct,\r\nor delete your personal information, object to certain processing activities,\r\nwithdraw consent where applicable, or request a copy of your personal data by\r\ncontacting our support team.\r\n</p>\r\n\r\n<h3>5.8 Changes to This Privacy Policy</h3>\r\n\r\n<p>\r\nWe reserve the right to update or modify this Privacy Policy at any time to reflect\r\nchanges in our services, legal obligations, or business practices. Any updates will\r\nbe posted on this page along with the revised effective date. Your continued use of\r\nour services after such changes constitutes your acceptance of the updated Privacy\r\nPolicy.\r\n</p>\r\n\r\n<h3>5.9 Contact Us</h3>\r\n\r\n<p>\r\nIf you have any questions, concerns, or requests regarding this Privacy Policy or\r\nour data handling practices, please contact our customer support team through the\r\ncontact information provided on our website. We will make reasonable efforts to\r\nrespond to your inquiry as soon as possible.\r\n</p>',	'en',	'1.0',	1,	0,	'2025-12-22 13:15:01.599271',	'2026-07-13 09:25:25.775201'),
(2,	'privacy_and_policy',	'table',	'Updated Privacy Policy',	'updated_privacy_policy',	'<h2>5. Privacy Policy</h2>\r\n\r\n<p>\r\nAt our company, we are committed to protecting your privacy and ensuring that your\r\npersonal information is handled in a secure and responsible manner. This Privacy\r\nPolicy explains how we collect, use, store, and protect the information you provide\r\nwhile using our website, mobile application, or related services.\r\n</p>\r\n\r\n<h3>5.1 Information We Collect</h3>\r\n\r\n<p>\r\nWe may collect personal information such as your name, email address, phone number,\r\nshipping address, billing address, payment details, and account credentials when you\r\nregister, place an order, or contact our support team. We may also collect technical\r\ninformation including your IP address, browser type, operating system, device\r\ninformation, and website usage statistics.\r\n</p>\r\n\r\n<h3>5.2 How We Use Your Information</h3>\r\n\r\n<p>\r\nYour information is used to provide and improve our services, process transactions,\r\nmanage your account, deliver products, respond to customer inquiries, personalize\r\nyour experience, send important notifications, and comply with applicable legal\r\nrequirements.\r\n</p>\r\n\r\n<h3>5.3 Cookies and Tracking Technologies</h3>\r\n\r\n<p>\r\nWe use cookies and similar technologies to remember your preferences, improve website\r\nperformance, analyze visitor behavior, and provide a better browsing experience.\r\nYou may disable cookies through your browser settings, although some features of the\r\nwebsite may become unavailable.\r\n</p>\r\n\r\n<h3>5.4 Sharing of Information</h3>\r\n\r\n<p>\r\nWe do not sell or rent your personal information. We may share your information with\r\ntrusted third-party service providers such as payment processors, shipping partners,\r\ncloud hosting providers, and analytics services only when necessary to operate our\r\nbusiness or comply with legal obligations.\r\n</p>\r\n\r\n<h3>5.5 Data Security</h3>\r\n\r\n<p>\r\nWe implement industry-standard technical, administrative, and physical safeguards to\r\nprotect your personal information against unauthorized access, disclosure, alteration,\r\nor destruction. While we strive to protect your data, no electronic transmission or\r\nstorage system can be guaranteed to be 100% secure.\r\n</p>\r\n\r\n<h3>5.6 Data Retention</h3>\r\n\r\n<p>\r\nWe retain your personal information only for as long as necessary to fulfill the\r\npurposes outlined in this Privacy Policy, resolve disputes, comply with legal\r\nrequirements, and enforce our agreements.\r\n</p>\r\n\r\n<h3>5.7 Your Rights</h3>\r\n\r\n<p>\r\nDepending on your jurisdiction, you may have the right to access, update, correct,\r\nor delete your personal information, object to certain processing activities,\r\nwithdraw consent where applicable, or request a copy of your personal data by\r\ncontacting our support team.\r\n</p>\r\n\r\n<h3>5.8 Changes to This Privacy Policy</h3>\r\n\r\n<p>\r\nWe reserve the right to update or modify this Privacy Policy at any time to reflect\r\nchanges in our services, legal obligations, or business practices. Any updates will\r\nbe posted on this page along with the revised effective date. Your continued use of\r\nour services after such changes constitutes your acceptance of the updated Privacy\r\nPolicy.\r\n</p>\r\n\r\n<h3>5.9 Contact Us</h3>\r\n\r\n<p>\r\nIf you have any questions, concerns, or requests regarding this Privacy Policy or\r\nour data handling practices, please contact our customer support team through the\r\ncontact information provided on our website. We will make reasonable efforts to\r\nrespond to your inquiry as soon as possible.\r\n</p>',	'en',	'1.1',	1,	0,	'2025-12-22 13:40:06.919093',	'2026-07-13 09:17:57.527087'),
(4,	'terms_and_conditions',	'uniform',	'Huge Laws',	'huge_laws',	'<p>\r\nWelcome to our website and services. By accessing, browsing, or using our platform,\r\nyou agree to comply with and be bound by these Terms and Conditions. If you do not\r\nagree with any part of these terms, you should discontinue using our services\r\nimmediately.\r\n</p>\r\n\r\n<h3>1. Acceptance of Terms</h3>\r\n\r\n<p>\r\nBy creating an account, placing an order, or using any part of our services, you\r\nconfirm that you have read, understood, and accepted these Terms and Conditions.\r\nThese terms apply to all users, visitors, customers, and others who access or use\r\nour platform.\r\n</p>\r\n\r\n<h3>2. User Responsibilities</h3>\r\n\r\n<p>\r\nYou agree to provide accurate, current, and complete information during registration\r\nand to keep your account information updated. You are responsible for maintaining\r\nthe confidentiality of your account credentials and for all activities that occur\r\nunder your account.\r\n</p>\r\n\r\n<h3>3. Orders and Payments</h3>\r\n\r\n<p>\r\nAll orders are subject to acceptance and availability. We reserve the right to\r\ncancel or refuse any order at our sole discretion. Prices, product availability,\r\nand promotions may change without prior notice. Payments must be completed using\r\nour approved payment methods before an order is processed.\r\n</p>\r\n\r\n<h3>4. Intellectual Property</h3>\r\n\r\n<p>\r\nAll content available on this platform, including text, images, logos, graphics,\r\nsoftware, and trademarks, is the property of the company or its licensors and is\r\nprotected by applicable intellectual property laws. Unauthorized copying,\r\ndistribution, or reproduction is strictly prohibited.\r\n</p>\r\n\r\n<h3>5. Prohibited Activities</h3>\r\n\r\n<p>\r\nUsers must not misuse the platform by attempting unauthorized access, transmitting\r\nmalicious software, violating applicable laws, interfering with website operations,\r\nor engaging in fraudulent or harmful activities. Any such actions may result in the\r\ntermination of your account and legal action where applicable.\r\n</p>\r\n\r\n<h3>6. Limitation of Liability</h3>\r\n\r\n<p>\r\nTo the maximum extent permitted by law, we shall not be liable for any indirect,\r\nincidental, special, consequential, or punitive damages arising from your use of\r\nour services, including loss of data, profits, or business opportunities.\r\n</p>\r\n\r\n<h3>7. Privacy</h3>\r\n\r\n<p>\r\nYour use of our services is also governed by our Privacy Policy, which explains how\r\nwe collect, use, store, and protect your personal information. By using our\r\nservices, you consent to the practices described in our Privacy Policy.\r\n</p>\r\n\r\n<h3>8. Changes to Terms</h3>\r\n\r\n<p>\r\nWe reserve the right to modify or update these Terms and Conditions at any time.\r\nAny changes will become effective immediately upon publication on this page.\r\nContinued use of the platform after such changes constitutes your acceptance of the\r\nupdated Terms and Conditions.\r\n</p>\r\n\r\n<h3>9. Governing Law</h3>\r\n\r\n<p>\r\nThese Terms and Conditions shall be governed by and interpreted in accordance with\r\nthe laws of the applicable jurisdiction. Any disputes arising from the use of our\r\nservices shall be subject to the exclusive jurisdiction of the competent courts.\r\n</p>\r\n\r\n<h3>10. Contact Information</h3>\r\n\r\n<p>\r\nIf you have any questions regarding these Terms and Conditions, please contact our\r\ncustomer support team using the contact details provided on our website. We will\r\nmake reasonable efforts to respond to your inquiries promptly.\r\n</p>',	'en',	'1.0',	1,	0,	'2026-01-16 12:37:59.048879',	'2026-07-13 09:25:48.693886'),
(5,	'agreement',	'uniform',	'Honest and Strict Laws',	'honest_and_strict_laws',	'<p>\r\nThis Agreement governs your access to and use of our website, mobile application,\r\nproducts, and related services. By creating an account, accessing our platform,\r\nor using any of our services, you acknowledge that you have read, understood,\r\nand agreed to be bound by the terms set forth in this Agreement.\r\n</p>\r\n\r\n<h3>1. Acceptance of Agreement</h3>\r\n\r\n<p>\r\nBy using our services, you agree to comply with this Agreement and all applicable\r\nlaws and regulations. If you do not agree with any provision of this Agreement,\r\nyou must immediately discontinue the use of our platform and services.\r\n</p>\r\n\r\n<h3>2. User Obligations</h3>\r\n\r\n<p>\r\nYou agree to provide accurate, complete, and up-to-date information when creating\r\nan account or using our services. You are solely responsible for maintaining the\r\nconfidentiality of your login credentials and for all activities performed through\r\nyour account.\r\n</p>\r\n\r\n<h3>3. Services</h3>\r\n\r\n<p>\r\nWe strive to provide reliable and uninterrupted services; however, we do not\r\nguarantee that the platform will always be available or free from errors. We\r\nreserve the right to modify, suspend, or discontinue any feature or service at\r\nour sole discretion without prior notice.\r\n</p>\r\n\r\n<h3>4. Payments and Fees</h3>\r\n\r\n<p>\r\nWhere applicable, users agree to pay all applicable fees, taxes, and charges\r\nassociated with the products or services purchased through our platform. Failure\r\nto make timely payments may result in suspension or termination of services.\r\n</p>\r\n\r\n<h3>5. Intellectual Property</h3>\r\n\r\n<p>\r\nAll content, software, logos, trademarks, graphics, and other materials available\r\non the platform are the exclusive property of the company or its licensors. You\r\nmay not copy, modify, distribute, or reproduce any content without prior written\r\npermission.\r\n</p>\r\n\r\n<h3>6. Confidentiality</h3>\r\n\r\n<p>\r\nBoth parties agree to maintain the confidentiality of any proprietary or sensitive\r\ninformation shared during the use of the services. Such information shall not be\r\ndisclosed to third parties except where required by law or with prior written\r\nconsent.\r\n</p>\r\n\r\n<h3>7. Limitation of Liability</h3>\r\n\r\n<p>\r\nTo the fullest extent permitted by law, the company shall not be liable for any\r\nindirect, incidental, consequential, or special damages arising from the use or\r\ninability to use the platform, including but not limited to loss of profits,\r\nbusiness interruption, or data loss.\r\n</p>\r\n\r\n<h3>8. Termination</h3>\r\n\r\n<p>\r\nWe reserve the right to suspend or terminate your account and access to our\r\nservices at any time if you violate this Agreement, engage in fraudulent activity,\r\nor misuse the platform. Upon termination, your right to use the services will\r\nimmediately cease.\r\n</p>\r\n\r\n<h3>9. Amendments</h3>\r\n\r\n<p>\r\nWe may revise or update this Agreement from time to time. Any modifications will\r\nbe effective upon posting on our website. Your continued use of the services after\r\nsuch changes constitutes your acceptance of the revised Agreement.\r\n</p>\r\n\r\n<h3>10. Governing Law</h3>\r\n\r\n<p>\r\nThis Agreement shall be governed by and interpreted in accordance with the\r\napplicable laws of the jurisdiction in which the company operates. Any disputes\r\narising under this Agreement shall be resolved exclusively in the competent courts\r\nof that jurisdiction.\r\n</p>\r\n\r\n<h3>11. Contact Information</h3>\r\n\r\n<p>\r\nIf you have any questions regarding this Agreement, please contact our customer\r\nsupport team using the contact information provided on our website. We will make\r\nreasonable efforts to respond to your inquiries in a timely manner.\r\n</p>',	'en',	'1.0',	1,	0,	'2026-01-16 12:43:43.983672',	'2026-07-13 09:26:07.758161');
