(2,	'Stretch  Scrub',	'stretch_scrub',	'Designed with four-way stretch fabric for maximum flexibility and comfort. Perfect for busy healthcare environments where mobility and durability are essential.',	'uniform',	1499.00,	100,	100,	'product_images/top_Tshirt-2.png',	10,	1,	1,	0,	'2026-01-02 12:59:50.376995',	'2026-07-08 08:31:32.680649',	1,	5,	NULL,	'top',	1.00,	0.00,	NULL,	NULL,	0,	NULL,	NULL,	NULL),
