(4,	'Men\'s Classic V-Neck Scrub',	'mens_classic_v_neck_scrub',	'A professional V-neck scrub top designed for doctors, nurses, and healthcare staff. Made from breathable, wrinkle-resistant fabric for maximum comfort throughout long shifts.',	'uniform',	1499.00,	100,	100,	'product_images/top3.jpeg',	10,	1,	1,	0,	'2026-01-03 05:52:00.539588',	'2026-07-08 08:31:43.903816',	1,	5,	NULL,	'top',	1.00,	0.00,	NULL,	NULL,	0,	NULL,	NULL,	NULL),
(5,	'Classic Straight-Leg Scrub',	'classic_straight_leg_scrub',	'Comfortable straight-leg scrub pants featuring an adjustable drawstring waistband, deep side pockets, and breathable fabric for everyday clinical wear',	'uniform',	500.00,	100,	100,	'product_images/Bottom-1.png',	10,	1,	1,	0,	'2026-01-03 05:58:41.599892',	'2026-07-24 04:50:17.995095',	1,	5,	NULL,	'bottom',	1.00,	0.00,	NULL,	NULL,	0,	NULL,	NULL,	NULL),
